import {afterAll,beforeAll,beforeEach,describe,expect,it} from 'vitest';
import {PrismaClient} from '@prisma/client';
import {execFileSync} from 'node:child_process';
import {randomUUID} from 'node:crypto';
import {telegram} from '@lowwin/better-auth-telegram';
import {TEST_TOKEN,signedLaunch} from './helpers';

const database=process.env.TEST_DATABASE_URL;
// Generated by better-auth 1.6.33 using fixture-only credentials, never a real account.
const legacyPasswordHash="5490727c045ea9de239ddb0e338aa20e:3133421c40f2a4089d6558e3cf3322de9e10917f9145cde429fb3c8e32e362b66b04a5d846a4677f861c9cb29c73c0e61acb6a59a720d3616a84c88c39774d09";
const legacyCookie="fixture-pre-upgrade-session-token.xxIBSefknYDC/oh/CczksP5VH6YcoUgsKlAkiwii7rQ=";

describe('reviewed Telegram compatibility surface',()=>{
 const options={botToken:TEST_TOKEN,botUsername:'lowin_fixture_bot',loginWidget:false as const,miniApp:{enabled:true,validateInitData:true}};
 it('keeps only the signed Mini App flow and its rate limits available',()=>{
  const plugin=telegram(options);
  expect(plugin.endpoints).toHaveProperty('signInWithMiniApp');
  expect(plugin.endpoints).not.toHaveProperty('signInWithTelegram');
  expect(plugin).not.toHaveProperty('init');
  expect(plugin.rateLimit.some(rule=>rule.pathMatcher('/telegram/miniapp/signin')&&rule.max===10)).toBe(true);
 });
 it('fails closed if unreviewed widget, OIDC or unsigned Mini App paths are enabled',()=>{
  for(const config of [{...options,loginWidget:true},{...options,oidc:{enabled:true}},{...options,miniApp:{enabled:true,validateInitData:false}}])
   expect(()=>telegram(config)).toThrow('requires signed Mini App authentication');
 });
});

describe.skipIf(!database)('installed authentication advisory boundaries on PostgreSQL',()=>{
 let db:PrismaClient,auth:ReturnType<typeof import('../src/modules/auth/server').createAuth>;
 const origin='http://localhost:3027';
 const request=(path:string,body?:unknown)=>new Request(origin+'/api/auth/'+path,{
  method:body===undefined?'GET':'POST',
  headers:{origin,'content-type':'application/json','x-forwarded-for':'198.18.73.11'},
  ...(body===undefined?{}:{body:JSON.stringify(body)}),
 });
 beforeAll(async()=>{
  const url=new URL(database!);
  if(!['127.0.0.1','localhost'].includes(url.hostname)||!url.pathname.endsWith('_test'))throw Error('Disposable loopback database required');
  Object.assign(process.env,{DATABASE_URL:database,DIRECT_URL:database,NODE_ENV:'test',APP_ENV:'local',
   BETTER_AUTH_URL:origin,MINI_APP_URL:origin,BETTER_AUTH_SECRET:'fixture-security-secret-at-least-thirty-two-characters',
   TELEGRAM_BOT_TOKEN:TEST_TOKEN,TELEGRAM_BOT_USERNAME:'lowin_fixture_bot',TELEGRAM_WEBHOOK_SECRET:'fixture-security-webhook-secret-thirty-two',
   DEV_IDENTITY_ENABLED:'false',DEV_POINTS_ENABLED:'false'});
  execFileSync(process.execPath,['node_modules/prisma/build/index.js','migrate','deploy'],{stdio:'pipe'});
  db=new PrismaClient({datasourceUrl:database});
  const {createAuth}=await import('../src/modules/auth/server');auth=createAuth(db);
 },60_000);
 beforeEach(async()=>{await db.rateLimit.deleteMany()});
 afterAll(async()=>{await db?.$disconnect();const {db:shared}=await import('../src/lib/db');await shared.$disconnect()});

 it('does not register the vulnerable optional Magic Link, OAuth Proxy or device-approval flows',async()=>{
  for(const [path,body] of [
   ['sign-in/magic-link',{email:'fixture@example.invalid'}],
   ['magic-link/verify',undefined],
   ['oauth-proxy-callback',undefined],
   ['device/code',{}],
   ['device/approve',{userCode:'TEST-CODE'}],
  ] as const){
   const response=await auth.handler(request(path,body));
   expect(response.status,path).toBe(404);
   expect(response.headers.getSetCookie().some(value=>value.includes('session_token='))).toBe(false);
  }
 });

 it('enforces the configured password limit during concurrent database-backed requests',async()=>{
  // Invalid bodies exercise the request limiter without password hashing,
  // account creation, email delivery or any provider request.
  const sessionsBefore=await db.session.count();
  const responses=await Promise.all(Array.from({length:24},()=>auth.handler(request('sign-in/email',{}))));
  expect(responses.filter(response=>response.status===400)).toHaveLength(5);
  expect(responses.filter(response=>response.status===429)).toHaveLength(19);
  for(const response of responses.filter(response=>response.status===429))expect(Number(response.headers.get('x-retry-after')??response.headers.get('retry-after'))).toBeGreaterThan(0);
  const rows=await db.rateLimit.findMany();
  expect(rows).toHaveLength(1);expect(rows[0].count).toBe(5);
  expect(await db.session.count()).toBe(sessionsBefore);
 });

 it('accepts a pre-upgrade password hash and session cookie without changing account identity',async()=>{
  const userId=randomUUID(),accountId=randomUUID(),email='legacy-'+userId+'@example.invalid';
  await db.user.create({data:{id:userId,name:'Legacy credential fixture',email,emailVerified:true,role:'admin'}});
  await db.account.create({data:{id:accountId,userId,accountId:userId,providerId:'credential',password:legacyPasswordHash}});
  await db.session.create({data:{id:randomUUID(),userId,token:'fixture-pre-upgrade-session-token',expiresAt:new Date(Date.now()+3600000)}});
  const session=await auth.api.getSession({headers:new Headers({cookie:'better-auth.session_token='+encodeURIComponent(legacyCookie)})});
  expect(session?.user.id).toBe(userId);
  const response=await auth.handler(request('sign-in/email',{email,password:'Fixture-pre-upgrade-password-12345'}));
  expect(response.status,await response.clone().text()).toBe(200);
  expect((await response.json()).user.id).toBe(userId);
  expect(await db.account.findMany({where:{userId}})).toEqual([expect.objectContaining({id:accountId,providerId:'credential',accountId:userId})]);
 });

 it('reuses a pre-upgrade Telegram account and preserves signed session cookies',async()=>{
  const userId=randomUUID(),accountId=randomUUID(),telegramId='781234567890';
  await db.user.create({data:{id:userId,name:'Existing Telegram fixture',telegramId,role:'member'}});
  await db.account.create({data:{id:accountId,userId,accountId:telegramId,providerId:'telegram',telegramId}});
  const response=await auth.handler(request('telegram/miniapp/signin',{initData:signedLaunch({user:JSON.stringify({id:Number(telegramId),first_name:'Existing Telegram fixture'})})}));
  expect(response.status,await response.clone().text()).toBe(200);
  const body=await response.json();expect(body.user.id).toBe(userId);
  const cookie=response.headers.getSetCookie().find(value=>value.includes('session_token='))!.split(';')[0];
  expect(cookie).toMatch(/^better-auth\.session_token=/);
  const session=await auth.api.getSession({headers:new Headers({cookie})});
  expect(session?.user.id).toBe(userId);expect(session?.session.id).toBe(body.session.id);
  expect(await db.account.findMany({where:{providerId:'telegram',accountId:telegramId}})).toEqual([expect.objectContaining({id:accountId,userId})]);
 });

 it('creates an ordinary member from signed Mini App data and rejects invalid signatures',async()=>{
  const telegramId=781234567891;
  const initData=signedLaunch({user:JSON.stringify({id:telegramId,first_name:'New Telegram fixture'})});
  const response=await auth.handler(request('telegram/miniapp/signin',{initData}));
  expect(response.status,await response.clone().text()).toBe(200);
  const body=await response.json();expect(body.user).toMatchObject({telegramId:String(telegramId),role:'member'});
  expect(await db.staffMember.findUnique({where:{userId:body.user.id}})).toBeNull();
  const before=await db.session.count();
  const invalid=await auth.handler(request('telegram/miniapp/signin',{initData:signedLaunch({},'wrong-token')}));
  expect(invalid.status).toBe(401);expect(invalid.headers.getSetCookie().some(value=>value.includes('session_token='))).toBe(false);
  expect(await db.session.count()).toBe(before);
 });
});
